package com.bankingax.task.c02;

import static org.junit.jupiter.api.Assertions.*;
import com.bankingax.core.api.DomainException;
import com.bankingax.core.caseport.InMemoryCasePort;
import com.bankingax.core.caseport.CasePort;
import com.bankingax.core.caseport.CreateCaseCommand;
import com.bankingax.core.caseport.ServiceCaseView;
import com.bankingax.core.caseport.ReviewStatus;
import com.bankingax.core.verification.*;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.Test;

class C02IntakeServiceTest {
 private final InMemoryCasePort cases=new InMemoryCasePort();
 private final FakeVerification verification=new FakeVerification();
 private StaffAgentPort staff=new FakeStaff();
 private C02IntakeService service(){ return new C02IntakeService(cases,verification,staff); }
 private C02IntakeService.Intake intake(LocalDate death,C02IntakeService.VisitStatus visit,C02IntakeService.DelegationMethod delegation){ return new C02IntakeService.Intake(new C02IntakeService.DecedentInput("고인",null,death,6800000),List.of(new C02IntakeService.HeirInput("h1","신청인",LocalDate.of(1980,1,1),"자녀",true,false,visit,delegation,delegation==C02IntakeService.DelegationMethod.RECEIPT?"R-1":null))); }
 private Map<String,C02IntakeService.DocumentStatus> complete(C02IntakeService.Intake intake){ Map<String,C02IntakeService.DocumentStatus> result=new HashMap<>(); for(var slot:service().requiredDocuments(intake)) if(slot.requirement()==C02IntakeService.Requirement.REQUIRED) result.put(slot.key(),C02IntakeService.DocumentStatus.UPLOADED); return result; }
 @Test void rejects_out_of_scope_death_and_minor(){ assertTrue(service().validate(intake(LocalDate.of(2007,12,31),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE)).outOfScope().contains("DEATH_DATE_BEFORE_2008")); var minor=new C02IntakeService.Intake(new C02IntakeService.DecedentInput("고인",null,LocalDate.of(2020,1,1),1),List.of(new C02IntakeService.HeirInput("h","미성년",LocalDate.now().minusYears(10),"자녀",true,false,C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE,null))); assertTrue(service().validate(minor).outOfScope().contains("MINOR_HEIR")); }
 @Test void derives_document_delegation_slots_and_blocks_missing(){ var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ABSENT,C02IntakeService.DelegationMethod.DOCUMENT); assertTrue(service().requiredDocuments(i).stream().anyMatch(s->s.documentTypeCode().equals("ABSENT_HEIR_POWER_OF_ATTORNEY"))); assertFalse(service().assessSubmission(i,Map.of()).submittable()); }
 @Test void accepts_the_synthetic_two_adult_document_delegation_demo_intake_and_derives_each_required_slot(){
  var scenario=new C02IntakeService.Intake(
   new C02IntakeService.DecedentInput("synthetic-decedent",LocalDate.of(1955,1,1),LocalDate.of(2020,1,1),6_000_000L),
   List.of(
    new C02IntakeService.HeirInput("attending","synthetic-applicant",LocalDate.of(1980,1,1),"child",true,false,C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE,null),
    new C02IntakeService.HeirInput("absent","synthetic-delegator",LocalDate.of(1982,1,1),"child",false,false,C02IntakeService.VisitStatus.ABSENT,C02IntakeService.DelegationMethod.DOCUMENT,null)));
  var slots=C02IntakeService.requiredDocuments(scenario);
  assertTrue(service().validate(scenario).errors().isEmpty());
  assertTrue(service().validate(scenario).outOfScope().isEmpty());
  assertTrue(slots.stream().anyMatch(s->s.key().equals("HEIR_IDENTITY_CARD:attending")));
  assertTrue(slots.stream().anyMatch(s->s.key().equals("ABSENT_HEIR_ID_COPY:absent")));
  assertTrue(slots.stream().anyMatch(s->s.key().equals("ABSENT_HEIR_SEAL_CERTIFICATE:absent")));
  assertTrue(slots.stream().anyMatch(s->s.key().equals("ABSENT_HEIR_POWER_OF_ATTORNEY:absent")));
  assertEquals(6, slots.stream().filter(s -> s.requirement()==C02IntakeService.Requirement.REQUIRED).count());
  assertEquals(8, slots.size(), "six uploadable required slots plus two visit-only slots");
  assertTrue(service().assessSubmission(scenario,complete(scenario)).submittable());
 }
 @Test void prepare_preserves_c02_application_visit_requirement_and_idempotency(){ var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var first=s.prepare(1,1001,"prepare-1",i,complete(i),"01012345678"); assertEquals(first,s.prepare(1,1001,"prepare-1",i,complete(i),"01012345678")); assertTrue(first.caseView().visitRequired()); assertTrue(first.caseView().application().containsKey("c02")); assertThrows(DomainException.class,()->s.prepare(2,1001,"prepare-1",i,complete(i),"01012345678")); assertNull(s.prepare(1,1002,"scope-1",intake(LocalDate.of(2007,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE),Map.of(),"010").caseView()); }
 @Test void resume_restores_existing_draft_and_prepare_reuses_or_revises_it_by_request_fingerprint(){ var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var s=service(); var first=s.prepare(1,1003,"prepare-resume",i,complete(i),"010"); assertEquals(first,s.prepare(1,1003,"prepare-resume",i,complete(i),"010")); var changed=intake(LocalDate.of(2021,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); assertEquals("DUPLICATE_REQUEST_CONFLICT",assertThrows(DomainException.class,()->s.prepare(1,1003,"prepare-resume",changed,complete(changed),"010")).code()); var revised=s.prepare(1,1003,"prepare-revised",changed,complete(changed),"010"); assertEquals(first.caseView().caseId(),revised.caseView().caseId()); assertEquals(first.caseView().revision()+1,revised.caseView().revision()); var restarted=new C02IntakeService(cases,new FakeVerification(),new FakeStaff()); var resumed=restarted.resume(1,1003); assertEquals(first.caseView().caseId(),resumed.caseView().caseId()); assertEquals(revised.caseView().revision(),resumed.caseView().revision()); assertEquals(revised.caseView().revision(),restarted.prepare(1,1003,"prepare-refresh",changed,complete(changed),"010").caseView().revision()); assertThrows(DomainException.class,()->restarted.resume(2,1003)); }
 @Test void draft_prepare_with_added_document_delegator_reuses_case_and_rebuilds_required_slots(){ var s=service(); var initial=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var first=s.prepare(1,1013,"prepare-initial",initial,Map.of(),"010"); var changed=new C02IntakeService.Intake(initial.decedent(),List.of(initial.heirs().get(0),new C02IntakeService.HeirInput("h2","delegator",LocalDate.of(1982,1,1),"child",false,false,C02IntakeService.VisitStatus.ABSENT,C02IntakeService.DelegationMethod.DOCUMENT,null))); var revised=s.prepare(1,1013,"prepare-add-heir",changed,Map.of(),"010"); assertEquals(first.caseView().caseId(),revised.caseView().caseId()); assertEquals(1,revised.caseView().revision()); assertTrue(revised.requiredDocuments().stream().anyMatch(slot->slot.key().equals("ABSENT_HEIR_POWER_OF_ATTORNEY:h2"))); }
 @Test void submit_rechecks_consent_documents_binding_idempotency_and_dispatches_staff(){ var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var prepared=s.prepare(1,1004,"prepare-submit",i,complete(i),"01012345678"); long id=prepared.caseView().caseId(); assertThrows(DomainException.class,()->s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-1","binding"))); s.recordConsentAndMockSignature(1,id,0,true,true); var issue=s.issueOtp(1,id,0); var binding=s.verifyOtp(1,issue.challengeId(),"000000"); var submitted=s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-1",binding.bindingId())); assertEquals("SUBMITTED",submitted.caseStatus()); assertEquals("INVALID_STATE",assertThrows(DomainException.class,()->s.prepare(1,1004,"prepare-after-submit",i,complete(i),"010")).code()); }
 @Test void unexpected_precheck_error_keeps_submitted_case_and_marks_manual_review(){ staff=(requestId,caseId,revision,snapshot)->{ throw new IllegalStateException("fixture internal detail"); }; var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var prepared=s.prepare(1,1040,"prepare-unexpected",i,complete(i),"010"); long id=prepared.caseView().caseId(); s.recordConsentAndMockSignature(1,id,0,true,true); var binding=s.verifyOtp(1,s.issueOtp(1,id,0).challengeId(),"000000"); var result=s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-unexpected",binding.bindingId())); assertEquals("SUBMITTED",result.caseStatus()); assertEquals("FAILED_NEEDS_STAFF",result.reviewStatus()); assertEquals("STAFF_PRECHECK_INTERNAL_ERROR",result.error().get("code")); assertFalse(result.error().toString().contains("fixture internal detail")); }
 @Test void failed_staff_transport_keeps_submitted_case_and_marks_manual_review(){ staff=(requestId,caseId,revision,snapshot)->{ throw new DomainException("STAFF_AGENT_UNAVAILABLE","fixture",true); }; var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var prepared=s.prepare(1,1004,"prepare-fail",i,complete(i),"010"); long id=prepared.caseView().caseId(); s.recordConsentAndMockSignature(1,id,0,true,true); var binding=s.verifyOtp(1,s.issueOtp(1,id,0).challengeId(),"000000"); var result=s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-fail",binding.bindingId())); assertEquals("SUBMITTED",result.caseStatus()); assertEquals("FAILED_NEEDS_STAFF",result.reviewStatus()); }
 @Test void document_metadata_is_versioned_and_a_submitted_case_is_rechecked_on_supplement(){ var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var prepared=s.prepare(1,1006,"prepare-doc",i,complete(i),"010"); long id=prepared.caseView().caseId(); s.recordConsentAndMockSignature(1,id,0,true,true); var binding=s.verifyOtp(1,s.issueOtp(1,id,0).challengeId(),"000000"); s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-doc",binding.bindingId())); var update=s.registerDocument(1,id,0,"doc-update",new DocumentPort.DocumentRegistration(id,0,"HEIR_IDENTITY_CARD:h1","id.pdf","application/pdf",1024,"fake://id-v2",C02IntakeService.DocumentStatus.NEEDS_SUPPLEMENT)); assertEquals(1,update.revision()); assertEquals("READY_FOR_STAFF",update.reviewStatus()); assertEquals(1,update.document().version()); assertEquals(1,s.documents(1,id).size()); assertThrows(DomainException.class,()->s.runStaffPrecheck(id,0,"stale")); var first=s.runStaffPrecheck(id,1,"manual-recheck"); assertEquals(first,s.runStaffPrecheck(id,1,"manual-recheck")); assertFalse(s.customerReview(1,id).finalStaffDecision()); }
 @Test void document_metadata_rejects_unknown_slot_and_invalid_mime(){ var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); long id=s.prepare(1,1007,"prepare-doc-invalid",i,complete(i),"010").caseView().caseId(); assertThrows(DomainException.class,()->s.registerDocument(1,id,0,"unknown",new DocumentPort.DocumentRegistration(id,0,"UNKNOWN:COMMON","x.pdf","application/pdf",1,"fake://x",C02IntakeService.DocumentStatus.UPLOADED))); assertThrows(DomainException.class,()->s.registerDocument(1,id,0,"mime",new DocumentPort.DocumentRegistration(id,0,"HEIR_IDENTITY_CARD:h1","x.exe","application/octet-stream",1,"fake://x",C02IntakeService.DocumentStatus.UPLOADED))); }
 @Test void staff_final_decision_requires_current_precheck_is_idempotent_and_creates_customer_web_notification(){ var s=service(); long id=submitted(s,1008); var command=new C02IntakeService.StaffDecisionCommand(900,id,0,"staff-proceed",C02IntakeService.StaffOutcome.PROCEED,"방문 전 안내"); var first=s.recordStaffDecision(command); assertEquals("SUBMITTED",first.currentCaseStatus()); assertEquals("REVIEW_PASSED",first.proposedCaseStatus()); assertEquals(first,s.recordStaffDecision(command)); assertEquals(1,s.customerNotifications(1).size()); assertEquals("PROCEED",s.customerNotifications(1).get(0).outcome()); assertThrows(DomainException.class,()->s.recordStaffDecision(new C02IntakeService.StaffDecisionCommand(900,id,0,"second",C02IntakeService.StaffOutcome.PROCEED,"방문 전 안내"))); assertThrows(DomainException.class,()->s.recordStaffDecision(new C02IntakeService.StaffDecisionCommand(901,id,0,"staff-proceed",C02IntakeService.StaffOutcome.PROCEED,"다른 내용"))); }
 @Test void staff_final_decision_rejects_stale_revision_and_maps_document_supplement_outcome(){ var s=service(); long id=submitted(s,1009); s.registerDocument(1,id,0,"revision-change",new DocumentPort.DocumentRegistration(id,0,"HEIR_IDENTITY_CARD:h1","id.pdf","application/pdf",1,"fake://id",C02IntakeService.DocumentStatus.NEEDS_SUPPLEMENT)); assertThrows(DomainException.class,()->s.recordStaffDecision(new C02IntakeService.StaffDecisionCommand(900,id,0,"stale",C02IntakeService.StaffOutcome.PROCEED,null))); var result=s.recordStaffDecision(new C02IntakeService.StaffDecisionCommand(900,id,1,"supplement",C02IntakeService.StaffOutcome.DOCUMENT_INSUFFICIENT,null)); assertEquals("REVIEW_REJECTED_DOCUMENT",result.proposedCaseStatus()); assertTrue(result.notification().message().contains("서류")); }
 @Test void customer_snapshot_echoes_intake_without_heir_birth_dates_and_shows_decision_after_it_is_recorded(){ var s=service(); long id=submitted(s,1010); var before=s.customerCaseSnapshot(1,id); assertEquals("h1",before.intake().heirs().get(0).personRef()); assertEquals("ATTENDING",before.intake().heirs().get(0).visitStatus()); assertNull(before.finalDecision()); assertNull(before.timeline()); s.recordStaffDecision(new C02IntakeService.StaffDecisionCommand(900,id,0,"snapshot-proceed",C02IntakeService.StaffOutcome.PROCEED,"방문 전 안내")); var after=s.customerCaseSnapshot(1,id); assertEquals("PROCEED",after.finalDecision().outcome()); assertEquals("방문 전 안내",after.finalDecision().customerMessage()); assertThrows(DomainException.class,()->s.customerCaseSnapshot(2,id)); }
 @Test void demo_seed_submit_keeps_every_check_except_the_sms_binding(){ var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); long id=s.prepare(1,1011,"prepare-seed",i,complete(i),"010").caseView().caseId(); assertEquals("CONSENT_OR_SIGNATURE_REQUIRED",assertThrows(DomainException.class,()->s.submitForDemoSeed(1,id,0,"seed-submit")).code()); s.recordConsentAndMockSignature(1,id,0,true,true); assertThrows(DomainException.class,()->s.submitForDemoSeed(2,id,0,"seed-other-customer")); assertThrows(DomainException.class,()->s.submitForDemoSeed(1,id,9,"seed-stale")); var first=s.submitForDemoSeed(1,id,0,"seed-submit"); assertEquals("SUBMITTED",first.caseStatus()); assertEquals(first,s.submitForDemoSeed(1,id,0,"seed-submit")); }
 @Test void demo_seed_submit_still_requires_the_required_documents(){ var s=service(); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); long id=s.prepare(1,1012,"prepare-seed-docs",i,Map.of(),"010").caseView().caseId(); s.recordConsentAndMockSignature(1,id,0,true,true); assertEquals("C02_SUBMISSION_BLOCKED",assertThrows(DomainException.class,()->s.submitForDemoSeed(1,id,0,"seed-no-docs")).code()); }
 private long submitted(C02IntakeService s,long workItem){ var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var prepared=s.prepare(1,workItem,"prepare-staff-"+workItem,i,complete(i),"010"); long id=prepared.caseView().caseId(); s.recordConsentAndMockSignature(1,id,0,true,true); var binding=s.verifyOtp(1,s.issueOtp(1,id,0).challengeId(),"000000"); s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-staff-"+workItem,binding.bindingId())); return id; }
 @Test void in_memory_binding_consume_and_case_submit_are_not_atomic(){ var delegate=new InMemoryCasePort(); CasePort failing=new CasePort(){ public ServiceCaseView create(CreateCaseCommand c){return delegate.create(c);} public ServiceCaseView submit(long actor,long id,int rev,String request){throw new DomainException("CASE_STORE_FAILURE","fixture",true);} public ServiceCaseView revise(long a,long b,int c,Map<String,Object>d,String e){return delegate.revise(a,b,c,d,e);} public ServiceCaseView cancel(long a,long b,int c){return delegate.cancel(a,b,c);} public ServiceCaseView recordCheckResult(long a,int b,ReviewStatus c){return delegate.recordCheckResult(a,b,c);} public ServiceCaseView get(long a,long b){return delegate.get(a,b);} public Optional<ServiceCaseView> findByWorkItem(long a,long b,com.bankingax.core.workflow.TaskCode c){return delegate.findByWorkItem(a,b,c);} }; var localVerification=new FakeVerification(); var s=new C02IntakeService(failing,localVerification,new FakeStaff()); var i=intake(LocalDate.of(2020,1,1),C02IntakeService.VisitStatus.ATTENDING,C02IntakeService.DelegationMethod.NONE); var prepared=s.prepare(1,1005,"prepare-atomic",i,complete(i),"010"); long id=prepared.caseView().caseId(); s.recordConsentAndMockSignature(1,id,0,true,true); var binding=s.verifyOtp(1,s.issueOtp(1,id,0).challengeId(),"000000"); assertThrows(DomainException.class,()->s.submit(new C02IntakeService.C02SubmitCommand(1,id,0,"submit-atomic",binding.bindingId()))); assertTrue(localVerification.consumed); }
 static final class FakeVerification implements VerificationPort { boolean consumed; long workItemId; int revision; public VerificationIssue issue(VerificationIssueCommand c){workItemId=c.workItemId(); revision=c.requestVersion(); return new VerificationIssue("challenge","010-****-5678",Instant.now().plusSeconds(60));} public VerificationBinding verify(VerificationVerifyCommand c){if(!"000000".equals(c.otp()))throw new DomainException("OTP_INVALID","bad"); return new VerificationBinding("binding",c.customerId(),workItemId,VerificationAction.C02_SUBMIT,revision,Instant.now().plusSeconds(60));} public void consume(VerificationConsumeCommand c){if(consumed||!"binding".equals(c.bindingId())||c.workItemId()!=workItemId)throw new DomainException("VERIFICATION_BINDING_INVALID","used"); consumed=true;} }
 static final class FakeStaff implements StaffAgentPort { public StaffAgentResponse check(String requestId,long caseId,int revision,Map<String,Object> snapshot){return new StaffAgentResponse("SUCCEEDED","READY_FOR_STAFF",List.of(Map.of("category","fixture")),null);} }
}
